reza:\"S/A\",    situacao:\"Irregular\", vinculo:\"Empresa Principal\" },\r\n  { casoId:99, caso:\"CASO TESTE\",      razaoSocial:\"MANGUINHOS DERIVADOS LTDA\",                cnpj:\"12.789.456/0001-33\", natureza:\"LTDA\",   situacao:\"Ativa\",     vinculo:\"Empresa Relacionada\" },\r\n];\r\n\r\nconst BENS_DATA = [\r\n  { casoId:1,  caso:\"CASO .30\",     tipo:\"Imóvel\",    subtipo:\"Residencial\", descricao:\"Casa em Barra da Tijuca\",  valor:1200000, registro:\"RJ-123456\" },\r\n  { casoId:1,  caso:\"CASO .30\",     tipo:\"Veículo\",   subtipo:\"Automóvel\",   descricao:\"BMW X5 2022 — ABC-1234\",   valor:380000,  registro:\"DETRAN-RJ\" },\r\n  { casoId:2,  caso:\"CASO QUÉOPS\", tipo:\"Imóvel\",    subtipo:\"Apartamento\", descricao:\"Apto Ipanema 120m²\",       valor:980000,  registro:\"RJ-345678\" },\r\n  { casoId:5,  caso:\"CASO PRATO FEITO\",   tipo:\"Aeronave\",  subtipo:\"Helicóptero\", descricao:\"Helicóptero EC130\",        valor:3500000, registro:\"ANAC-1234\" },\r\n  { casoId:5,  caso:\"CASO PRATO FEITO\",   tipo:\"Imóvel\",    subtipo:\"Fazenda\",     descricao:\"Fazenda 500ha — MG\",       valor:2800000, registro:\"MG-567890\" },\r\n  { casoId:7,  caso:\"CASO VALE O ESCRITO\",  tipo:\"Veículo\",   subtipo:\"SUV\",         descricao:\"Porsche Cayenne — MNO\",    valor:520000,  registro:\"DETRAN-RJ\" },\r\n  { casoId:8,  caso:\"CASO PEIXOTO\",  tipo:\"Imóvel\",    subtipo:\"Comercial\",   descricao:\"Galpão Industrial SP\",     valor:1800000, registro:\"SP-789012\" },\r\n  { casoId:10, caso:\"CASO FARMÁCIAS\",   tipo:\"Embarcação\",subtipo:\"Lancha\",      descricao:\"Lancha 38 pés — RJ-98765\", valor:680000,  registro:\"Capitania\" },\r\n  { casoId:99, caso:\"CASO TESTE\",      tipo:\"Imóvel\",    subtipo:\"Residencial\", descricao:\"Casa em Niterói — Charitas\",valor:1450000, registro:\"RJ-987001\" },\r\n  { casoId:99, caso:\"CASO TESTE\",      tipo:\"Veículo\",   subtipo:\"Automóvel\",   descricao:\"Mercedes GLE 2023 — RJX-1199\", valor:420000,  registro:\"DETRAN-RJ\" },\r\n  { casoId:99, caso:\"CASO TESTE\",      tipo:\"Imóvel\",    subtipo:\"Comercial\",   descricao:\"Sala Comercial Centro RJ 80m²\", valor:650000,  registro:\"RJ-987002\" },\r\n];\r\n\r\nconst ATIVIDADES = [\r\n  { hora:\"09:14\", usuario:\"Det. Ana Paula\",   acao:\"Adicionou PJ\",      caso:\"CASO QUÉOPS\", tipo:\"➕\" },\r\n  { hora:\"08:52\", usuario:\"Det. Carlos Lima\", acao:\"Editou ilha OSINT\", caso:\"CASO .30\",     tipo:\"✏️\" },\r\n  { hora:\"08:30\", usuario:\"Det. Marcos\",      acao:\"Novo bem imóvel\",   caso:\"CASO PEIXOTO\",  tipo:\"➕\" },\r\n  { hora:\"Ontem\", usuario:\"Analista Lima\",    acao:\"Gerou relatório\",   caso:\"CASO MORRO DO MORCEGO\", tipo:\"📄\" },\r\n  { hora:\"Ontem\", usuario:\"Det. Carlos Lima\", acao:\"Cadastrou veículo\", caso:\"CASO PRATO FEITO\",   tipo:\"➕\" },\r\n];\r\n\r\nconst STATUS_EST = {\r\n  \"Ativo\":             { bg:\"rgba(74,222,128,.1)\", cor:\"#4ade80\", borda:\"rgba(74,222,128,.25)\", dot:\"#4ade80\" },\r\n  \"Concluído\":        { bg:\"#eef2ff\", cor:\"#1a6fc4\", borda:\"#b0c4ee\", dot:\"#1a6fc4\" },\r\n  \"Aguardando Início\": { bg:\"rgba(148,163,184,.08)\", cor:\"rgba(148,163,184,.6)\", borda:\"rgba(148,163,184,.15)\", dot:\"#94a3b8\" },\r\n};\r\n\r\nconst ILHA_ICONES = {\r\n  \"Estudo de Caso\": <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.5\" strokeLinecap=\"round\" strokeLinejoin=\"round\" width=\"12\" height=\"12\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><circle cx=\"10.5\" cy=\"14.5\" r=\"2.5\"/><line x1=\"12.5\" y1=\"16.5\" x2=\"14\" y2=\"18\"/></svg>,\r\n  \"Mineração\":      <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.5\" strokeLinecap=\"round\" strokeLinejoin=\"round\" width=\"12\" height=\"12\"><ellipse cx=\"12\" cy=\"5\" rx=\"9\" ry=\"3\"/><path d=\"M21 12c0 1.66-4 3-9 3s-9-1.34-9-3\"/><path d=\"M3 5v14c0 1.66 4 3 9 3s9-1.34 9-3V5\"/></svg>,\r\n  \"OSINT\":          <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.5\" strokeLinecap=\"round\" strokeLinejoin=\"round\" width=\"12\" height=\"12\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"2\" y1=\"12\" x2=\"22\" y2=\"12\"/><path d=\"M12 2a15.3 15.3 0 0 1 4 10 15.3 15.3 0 0 1-4 10 15.3 15.3 0 0 1-4-10 15.3 15.3 0 0 1 4-10z\"/></svg>,\r\n  \"Relatório Técnico\": <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.5\" strokeLinecap=\"round\" strokeLinejoin=\"round\" width=\"12\" height=\"12\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><polyline points=\"14 2 14 8 20 8\"/><line x1=\"16\" y1=\"13\" x2=\"8\" y2=\"13\"/><line x1=\"16\" y1=\"17\" x2=\"8\" y2=\"17\"/><polyline points=\"10 9 9 9 8 9\"/></svg>,\r\n};\r\n\r\nconst ILHA_CORES = {\r\n  \"Estudo de Caso\":   { bg:\"#fff8f0\", borda:\"#f0c060\", topo:\"#b07d28\" },\r\n  \"Mineração\":        { bg:\"#f0eeff\", borda:\"#b0a0e0\", topo:\"#5a3e8a\" },\r\n  \"OSINT\":            { bg:\"#eef5ff\", borda:\"#90c0f0\", topo:\"#1a6fc4\" },\r\n  \"Relatório Técnico\":{ bg:\"#f0fff4\", borda:\"#90d0b0\", topo:\"#1a8c4a\" },\r\n};\r\n\r\nconst fmt = v => \"R$ \" + Number(v).toLocaleString(\"pt-BR\");\r\n\r\n/* ── Data de hoje formatada dd/mm/yyyy ── */\r\nfunction hoje() {\r\n  const d = new Date();\r\n  const p = n => String(n).padStart(2,'0');\r\n  return p(d.getDate())+\"/\"+p(d.getMonth()+1)+\"/\"+d.getFullYear();\r\n}\r\n\r\n/* ── Calcula dias úteis entre duas datas ── */\r\nfunction diasUteis(inicio, fim) {\r\n  if (!inicio || !fim) return null;\r\n  const toDate = str => {\r\n    const [d,mo,y] = str.split(\"/\");\r\n    return new Date(y, mo-1, d);\r\n  };\r\n  let d1 = toDate(inicio);\r\n  let d2 = toDate(fim);\r\n  if (d1 > d2) [d1, d2] = [d2, d1];\r\n  let count = 0;\r\n  const cur = new Date(d1);\r\n  while (cur <= d2) {\r\n    const dow = cur.getDay();\r\n    if (dow !== 0 && dow !== 6) count++;\r\n    cur.setDate(cur.getDate() + 1);\r\n  }\r\n  return count;\r\n}\r\n\r\n/* ── Caixas de ilha com casos dentro ── */\r\nfunction CaixaIlha({ nomeIlha, podeAdmin }) {\r\n  const icone = ILHA_ICONES[nomeIlha];\r\n  const [concluidos, setConcluidos] = useState(true);\r\n  const [hovBar, setHovBar] = useState(false);\r\n\r\n  const CORES_ILHA = {\r\n    \"Estudo de Caso\":    { g:\"linear-gradient(135deg,#b07d28,#d4a84b)\", sh:\"rgba(176,125,40,.5)\", acc:\"#d4a84b\" },\r\n    \"Mineração\":         { g:\"linear-gradient(135deg,#5a3e8a,#7c5abf)\", sh:\"rgba(90,62,138,.5)\",  acc:\"#a78bfa\" },\r\n    \"OSINT\":             { g:\"linear-gradient(135deg,#1565C0,#3b82f6)\", sh:\"rgba(21,101,192,.5)\", acc:\"#60a5fa\" },\r\n    \"Relatório Técnico\": { g:\"linear-gradient(135deg,#157A45,#22c55e)\", sh:\"rgba(21,122,69,.5)\",  acc:\"#4ade80\" },\r\n  };\r\n\r\n  const cores = CORES_ILHA[nomeIlha] || CORES_ILHA[\"Mineração\"];\r\n\r\n  const casosAndamento = CASOS.filter(c => {\r\n    const ilha = (ILHAS_DATA[c.id]||[]).find(i=>i.nome===nomeIlha);\r\n    return ilha && ilha.status===\"Em andamento\";\r\n  }).map(c => ({ ...c, ilhaInfo:(ILHAS_DATA[c.id]||[]).find(i=>i.nome===nomeIlha) }));\r\n\r\n  const casosConcl = CASOS.filter(c => {\r\n    const ilha = (ILHAS_DATA[c.id]||[]).find(i=>i.nome===nomeIlha);\r\n    return ilha && ilha.status===\"Concluída\";\r\n  }).map(c => ({ ...c, ilhaInfo:(ILHAS_DATA[c.id]||[]).find(i=>i.nome===nomeIlha) }));\r\n\r\n  const total = casosAndamento.length + casosConcl.length;\r\n  const pct   = total > 0 ? Math.round((casosConcl.length/total)*100) : 0;\r\n\r\n  const limparConcluidos = () => {\r\n    if (!podeAdmin) {\r\n      alert(\"⛔ Acesso negado.\\n\\nApenas Administradores podem limpar os concluídos.\");\r\n      return;\r\n    }\r\n    if (window.confirm(\"Confirma a limpeza dos casos concluídos desta ilha?\")) {\r\n      setConcluidos(false);\r\n    }\r\n  };\r\n\r\n  return (\r\n    <div style={{ borderRadius:8, overflow:\"hidden\",\r\n                  border:\"1px solid rgba(255,255,255,.07)\",\r\n                  background:\"#0f1520\",\r\n                  flex:1, minWidth:180, display:\"flex\", flexDirection:\"column\",\r\n                  boxShadow:\"0 4px 16px rgba(0,0,0,.25)\" }}>\r\n\r\n      {/* Header com gradiente */}\r\n      <div translate=\"no\" style={{ background:cores.g, flexShrink:0,\r\n                    boxShadow:\"0 2px 10px \"+cores.sh }}>\r\n        <div style={{ padding:\"8px 12px\", display:\"flex\", alignItems:\"center\", gap:8 }}>\r\n          <span style={{ display:\"flex\",alignItems:\"center\",justifyContent:\"center\",\r\n                         width:28,height:28,borderRadius:8,flexShrink:0,\r\n                         background:\"rgba(0,0,0,.20)\",color:\"#fff\" }}>\r\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" strokeWidth=\"1.6\"\r\n                 strokeLinecap=\"round\" strokeLinejoin=\"round\" width=\"15\" height=\"15\">\r\n              {icone.props.children}\r\n            </svg>\r\n          </span>\r\n          <span style={{ fontSize:11, fontWeight:700, color:\"#fff\",\r\n                         flex:1, letterSpacing:\".02em\" }}>{nomeIlha}</span>\r\n          <span style={{ fontSize:9, background:\"rgba(0,0,0,.22)\",\r\n                         borderRadius:10, padding:\"1px 7px\",\r\n                         color:\"rgba(255,255,255,.85)\", fontWeight:700 }}>\r\n            {casosConcl.length}/{total}\r\n          </span>\r\n          <span style={{ fontSize:9, fontWeight:800, color:cores.acc,\r\n                         background:\"rgba(0,0,0,.25)\", borderRadius:10,\r\n                         padding:\"1px 7px\", letterSpacing:\".01em\" }}>\r\n            {pct}%\r\n          </span>\r\n        </div>\r\n        {/* Barra de progresso aprimorada */}\r\n        <div onMouseEnter={()=>setHovBar(true)} onMouseLeave={()=>setHovBar(false)}\r\n          style={{ height:6, background:\"rgba(0,0,0,.3)\", position:\"relative\", cursor:\"default\" }}>\r\n          <div style={{ height:\"100%\", width:pct+\"%\",\r\n                        background:cores.acc,\r\n                        transition:\"width .4s ease\",\r\n                        boxShadow:\"0 0 6px \"+cores.acc+\"88\" }}/>\r\n          {hovBar&&(\r\n            <div style={{ position:\"absolute\",top:-28,left:\"50%\",transform:\"translateX(-50%)\",\r\n                          background:\"rgba(0,0,0,.85)\",borderRadius:5,padding:\"3px 8px\",\r\n                          fontSize:9,color:\"#fff\",whiteSpace:\"nowrap\",zIndex:50,\r\n                          border:\"1px solid rgba(255,255,255,.1)\",pointerEvents:\"none\" }}>\r\n              {casosConcl.length} concluído{casosConcl.length!==1?\"s\":\"\"} de {total} caso{total!==1?\"s\":\"\"}\r\n            </div>\r\n          )}\r\n        </div>\r\n      </div>\r\n\r\n      {/* Corpo — scroll máx 200px */}\r\n      <div style={{ padding:\"10px 12px\", overflowY:\"auto\",\r\n                    maxHeight:200, flex:1 }}>\r\n\r\n        {/* Em andamento */}\r\n        <div style={{ marginBottom:8 }}>\r\n          <div style={{ fontSize:8, fontWeight:700, color:cores.acc,\r\n                        textTransform:\"uppercase\", letterSpacing:\".12em\",\r\n                        marginBottom:5 }}>\r\n            ● Em andamento ({casosAndamento.length})\r\n          </div>\r\n          {casosAndamento.length===0 ? (\r\n            <div style={{ fontSize:10, color:\"rgba(255,255,255,.22)\",\r\n                          fontStyle:\"italic\" }}>Nenhum caso ativo</div>\r\n          ) : casosAndamento.map(c=>(\r\n            <div key={c.id} style={{ display:\"flex\", alignItems:\"center\",\r\n                                      gap:6, marginBottom:5, paddingBottom:5,\r\n                                      borderBottom:\"1px solid rgba(255,255,255,.05)\" }}>\r\n              <span style={{ width:5, height:5, borderRadius:\"50%\",\r\n                             background:cores.acc, flexShrink:0,\r\n                             boxShadow:\"0 0 4px \"+cores.acc }}/>\r\n              <span style={{ fontSize:10, fontWeight:600,\r\n                             color:\"rgba(255,255,255,.8)\", flex:1,\r\n                             overflow:\"hidden\", textOverflow:\"ellipsis\",\r\n                             whiteSpace:\"nowrap\" }}>{c.nome}</span>\r\n              {c.ilhaInfo?.inicio && (\r\n                <span style={{ fontSize:8, color:\"rgba(255,255,255,.3)\",\r\n                               flexShrink:0, fontFamily:\"'JetBrains Mono',monospace\" }}>\r\n                  {c.ilhaInfo.inicio}\r\n                </span>\r\n              )}\r\n            </div>\r\n          ))}\r\n        </div>\r\n\r\n        {/* Separador */}\r\n        <div style={{ borderTop:\"1px solid rgba(255,255,255,.07)\", marginBottom:8 }}/>\r\n\r\n        {/* Concluídos */}\r\n        <div>\r\n          <div style={{ fontSize:8, fontWeight:700, color:\"#4ade80\",\r\n                        textTransform:\"uppercase\", letterSpacing:\".12em\",\r\n                        marginBottom:5 }}>\r\n            ✓ Concluídos ({casosConcl.length})\r\n          </div>\r\n          {!concluidos ? (\r\n            <div style={{ fontSize:9, color:\"rgba(255,255,255,.2)\",\r\n                          fontStyle:\"italic\" }}>\r\n              Lista limpa pelo administrador.\r\n            </div>\r\n          ) : casosConcl.length===0 ? (\r\n            <div style={{ fontSize:10, color:\"rgba(255,255,255,.22)\",\r\n                          fontStyle:\"italic\" }}>Nenhum caso</div>\r\n          ) : casosConcl.map(c=>{\r\n            const du = diasUteis(c.ilhaInfo?.inicio, c.ilhaInfo?.fim);\r\n            return (\r\n              <div key={c.id} style={{ marginBottom:5, paddingBottom:5,\r\n                                        borderBottom:\"1px solid rgba(255,255,255,.04)\" }}>\r\n                <div style={{ display:\"flex\", alignItems:\"center\", gap:6 }}>\r\n                  <span style={{ width:5, height:5, borderRadius:\"50%\",\r\n                                 background:\"#4ade80\", flexShrink:0 }}/>\r\n                  <span style={{ fontSize:10, color:\"rgba(255,255,255,.3)\",\r\n                                 textDecoration:\"line-through\", flex:1,\r\n                                 overflow:\"hidden\", textOverflow:\"ellipsis\",\r\n                                 whiteSpace:\"nowrap\" }}>{c.nome}</span>\r\n                </div>\r\n                {c.ilhaInfo?.inicio && (\r\n                  <div style={{ fontSize:8, color:\"rgba(255,255,255,.2)\",\r\n                                marginTop:2, paddingLeft:11,\r\n                                fontFamily:\"'JetBrains Mono',monospace\",\r\n                                display:\"flex\", gap:6, alignItems:\"center\" }}>\r\n                    <span>{c.ilhaInfo.inicio}</span>\r\n                    {c.ilhaInfo.fim && <span>→ {c.ilhaInfo.fim}</span>}\r\n                    {du && (\r\n                      <span style={{ background:\"rgba(74,222,128,.1)\",\r\n                                     color:\"#4ade80\", borderRadius:10,\r\n                                     padding:\"0px 5px\", fontSize:7,\r\n                                     border:\"1px solid rgba(74,222,128,.2)\" }}>\r\n                        {du}du\r\n                      </span>\r\n                    )}\r\n                  </div>\r\n                )}\r\n              </div>\r\n            );\r\n          })}\r\n        </div>\r\n      </div>\r\n\r\n      {/* Rodapé */}\r\n      <div className=\"no-print\" style={{ padding:\"6px 12px\", background:\"rgba(0,0,0,.3)\",\r\n                    borderTop:\"1px solid rgba(255,255,255,.05)\",\r\n                    display:\"flex\", justifyContent:\"space-between\",\r\n                    alignItems:\"center\", flexShrink:0 }}>\r\n        <button onClick={limparConcluidos}\r\n          style={{ fontSize:8, color:podeAdmin?\"rgba(255,255,255,.35)\":\"rgba(255,255,255,.15)\",\r\n                   background:\"none\", border:\"1px solid rgba(255,255,255,.1)\",\r\n                   borderRadius:4, padding:\"2px 7px\", cursor:\"pointer\",\r\n                   letterSpacing:\".04em\" }}>\r\n          🗑 Limpar\r\n        </button>\r\n        <span style={{ fontSize:13, fontWeight:800, color:cores.acc,\r\n                       letterSpacing:\"-.01em\" }}>\r\n          {casosAndamento.length}\r\n        </span>\r\n      </div>\r\n    </div>\r\n  );\r\n}\r\n\r\n/* ── Gráfico de Gantt ── */\r\nfunction GraficoGantt({ casoFiltro }) {\r\n  const [tooltip, setTooltip] = useState(null);\r\n\r\n  const casosSel = casoFiltro\r\n    ? CASOS.filter(c=>c.id===casoFiltro)\r\n    : CASOS.filter(c=>c.status===\"Ativo\"||c.status===\"Concluído\");\r\n\r\n  const toDate = str => {\r\n    if (!str||str===\"—\") return null;\r\n    const [d,mo,y] = str.split(\"/\");\r\n    return new Date(y, mo-1, d);\r\n  };\r\n\r\n  const allDates = [];\r\n  casosSel.forEach(c=>{\r\n    (ILHAS_DATA[c.id]||[]).forEach(ilha=>{\r\n      if (ilha.inicio) allDates.push(toDate(ilha.inicio));\r\n      if (ilha.fim)    allDates.push(toDate(ilha.fim));\r\n    });\r\n  });\r\n  const minDate   = new Date(2025,0,1); // Fixo em Janeiro/2025\r\n  const maxDate   = allDates.length ? new Date(Math.max(...allDates)) : new Date(2025,11,31);\r\n  const totalDias = Math.max((maxDate-minDate)/86400000, 1);\r\n  const pct = date => !date ? 0 : Math.max(0,Math.min(100,((date-minDate)/86400000/totalDias)*100));\r\n\r\n  const meses=[];\r\n  const cur=new Date(minDate.getFullYear(),minDate.getMonth(),1);\r\n  while(cur<=maxDate){meses.push(new Date(cur));cur.setMonth(cur.getMonth()+1);}\r\n  const nm=[\"Jan\",\"Fev\",\"Mar\",\"Abr\",\"Mai\",\"Jun\",\"Jul\",\"Ago\",\"Set\",\"Out\",\"Nov\",\"Dez\"];\r\n\r\n  const handleMouseEnter = (e, caso, ilha) => {\r\n    const du = diasUteis(ilha.inicio, ilha.fim || hoje());\r\n    setTooltip({\r\n      x: e.clientX,\r\n      y: e.clientY,\r\n      caso: caso.nome,\r\n      ilha: ilha.nome,\r\n      inicio: ilha.inicio,\r\n      fim: ilha.fim,\r\n      status: ilha.status,\r\n      du,\r\n    });\r\n  };\r\n\r\n  const handleMouseLeave = () => setTooltip(null);\r\n\r\n  return (\r\n    <div id=\"gantt-wrapper\" style={{ background:C.branco, borderRadius:4, overflow:\"hidden\",\r\n                  border:\"1px solid \"+C.cinzaL, boxShadow:\"0 2px 8px rgba(0,0,0,.06)\",\r\n                  position:\"relative\" }}>\r\n\r\n      {/* ── Tooltip flutuante ── */}\r\n      {tooltip && (\r\n        <div style={{\r\n          position:\"fixed\",\r\n          left: tooltip.x + 14,\r\n          top:  tooltip.y - 10,\r\n          zIndex:9999,\r\n          background:\"#1a1f2e\",\r\n          border:\"1px solid \"+C.dourado,\r\n          borderRadius:6,\r\n          padding:\"10px 14px\",\r\n          boxShadow:\"0 8px 24px rgba(0,0,0,.35)\",\r\n          pointerEvents:\"none\",\r\n          minWidth:200,\r\n          maxWidth:260,\r\n        }}>\r\n          <div style={{ fontSize:12,fontWeight:700,color:C.douradoC,\r\n                        marginBottom:6,borderBottom:\"1px solid rgba(200,151,58,.3)\",\r\n                        paddingBottom:6 }}>\r\n            📁 {tooltip.caso}\r\n          </div>\r\n          <div style={{ fontSize:11,color:\"#fff\",marginBottom:4,\r\n                        display:\"flex\",alignItems:\"center\",gap:6 }}>\r\n            <span style={{ display:\"flex\",alignItems:\"center\",justifyContent:\"center\",\r\n                           width:15,height:15,borderRadius:4,flexShrink:0,\r\n                           background:(ILHA_CORES[tooltip.ilha]||{}).topo||\"#555\",\r\n                           color:\"#fff\",opacity:0.9 }}>\r\n              {ILHA_ICONES[tooltip.ilha]}\r\n            </span>\r\n            {tooltip.ilha}\r\n          </div>\r\n          <div style={{ fontSize:10,color:\"rgba(255,255,255,.65)\",lineHeight:1.8 }}>\r\n            <div>📅 Início: <strong style={{ color:\"#fff\" }}>{tooltip.inicio || \"—\"}</strong></div>\r\n            <div>🏁 Término: <strong style={{ color: tooltip.fim ? C.verde : C.amarelo }}>\r\n              {tooltip.fim || \"Em andamento\"}\r\n            </strong></div>\r\n            <div style={{ marginTop:4 }}>\r\n              <span style={{ background: tooltip.status===\"Concluída\"\r\n                               ? \"rgba(26,140,74,.25)\" : \"rgba(26,111,196,.25)\",\r\n                             color: tooltip.status===\"Concluída\" ? \"#5de87a\" : \"#7ab8f5\",\r\n                             borderRadius:10, padding:\"2px 8px\",\r\n                             fontSize:10, fontWeight:700 }}>\r\n                ⏱ {tooltip.du} Dias Úteis\r\n              </span>\r\n            </div>\r\n          </div>\r\n        </div>\r\n      )}\r\n\r\n      {/* ── Título fixo ── */}\r\n      <div id=\"gantt-title-bar\" style={{ padding:\"12px 16px\", background:\"#1a1f2e\",\r\n                    borderBottom:\"2px solid \"+C.dourado, flexShrink:0 }}>\r\n        <span style={{ fontSize:13,fontWeight:700,color:\"#fff\" }}>\r\n          📅 Gráfico de Gantt — Fases por Caso\r\n        </span>\r\n      </div>\r\n\r\n      {/* ── Container com scroll horizontal ── */}\r\n      <div id=\"gantt-outer-scroll\" style={{ overflowX:\"auto\" }}>\r\n\r\n        {/* Header meses — FIXO (sticky top) */}\r\n        <div id=\"gantt-months-header\" style={{ display:\"flex\", minWidth:700,\r\n                      position:\"sticky\", top:0, zIndex:10,\r\n                      background:\"#f5f7fa\" }}>\r\n          <div style={{ width:230, flexShrink:0, padding:\"6px 12px\",\r\n                        background:\"#f5f7fa\", borderBottom:\"1px solid \"+C.cinzaL,\r\n                        borderRight:\"1px solid \"+C.cinzaL }}>\r\n            <span style={{ fontSize:10,fontWeight:700,color:C.cinzaT,\r\n                           textTransform:\"uppercase\",letterSpacing:\".06em\" }}>\r\n              Caso / Fase\r\n            </span>\r\n          </div>\r\n          <div style={{ flex:1, display:\"flex\",\r\n                        borderBottom:\"1px solid \"+C.cinzaL }}>\r\n            {meses.map((mes,i)=>(\r\n              <div key={i} style={{ flex:1, padding:\"6px 4px\", textAlign:\"center\",\r\n                                    borderRight:\"1px solid \"+C.cinzaL }}>\r\n                <span style={{ fontSize:9,fontWeight:700,color:C.cinzaT }}>\r\n                  {nm[mes.getMonth()]} {mes.getFullYear()}\r\n                </span>\r\n              </div>\r\n            ))}\r\n          </div>\r\n        </div>\r\n\r\n        {/* Linhas dos casos — com scroll vertical */}\r\n        <div id=\"gantt-rows-scroll\" style={{ maxHeight:420, overflowY:\"auto\" }}>\r\n          {casosSel.map(caso=>{\r\n            const ilhas=ILHAS_DATA[caso.id]||[];\r\n            return (\r\n              <div key={caso.id} className=\"gantt-case-group\">\r\n                {/* Linha do caso */}\r\n                <div className=\"gantt-case-row\" style={{ display:\"flex\", minWidth:700,\r\n                              background:\"rgba(123,30,46,.04)\",\r\n                              borderBottom:\"1px solid \"+C.cinzaL }}>\r\n                  <div style={{ width:230, flexShrink:0, padding:\"8px 12px\",\r\n                                borderRight:\"1px solid \"+C.cinzaL }}>\r\n                    <span style={{ fontSize:12,fontWeight:700,color:C.bordo }}>\r\n                      {caso.nome}\r\n                    </span>\r\n                  </div>\r\n                  <div style={{ flex:1 }}/>\r\n                </div>\r\n\r\n                {/* Ilhas */}\r\n                {ilhas.map((ilha,ii)=>{\r\n                  const left = ilha.inicio ? pct(toDate(ilha.inicio)) : null;\r\n                  const w    = ilha.inicio&&ilha.fim\r\n                    ? Math.max(1,((toDate(ilha.fim)-toDate(ilha.inicio))/86400000/totalDias)*100)\r\n                    : null;\r\n                  const wAtivo = ilha.inicio&&ilha.status===\"Em andamento\"\r\n                    ? Math.max(1,((new Date()-toDate(ilha.inicio))/86400000/totalDias)*100)\r\n                    : null;\r\n                  const barCor = ilha.status===\"Concluída\" ? \"#1a8c4a\"\r\n                                : ilha.status===\"Em andamento\" ? \"#1a6fc4\" : \"#ddd\";\r\n\r\n                  return (\r\n                    <div key={ii} className=\"gantt-phase-row\" style={{ display:\"flex\", minWidth:700,\r\n                                           borderBottom:\"1px solid \"+C.cinzaL }}>\r\n                      <div style={{ width:230, flexShrink:0,\r\n                                    padding:\"7px 12px 7px 24px\",\r\n                                    borderRight:\"1px solid \"+C.cinzaL,\r\n                                    display:\"flex\", alignItems:\"center\", gap:6 }}>\r\n                        <span style={{ display:\"flex\",alignItems:\"center\",justifyContent:\"center\",\r\n                                        width:18,height:18,borderRadius:5,flexShrink:0,\r\n                                        background:(ILHA_CORES[ilha.nome]||{}).topo||\"#555\",\r\n                                        color:\"#fff\",opacity:0.88 }}>\r\n                          {ILHA_ICONES[ilha.nome]}\r\n                        </span>\r\n                        <span style={{ fontSize:11,color:C.texto }}>{ilha.nome}</span>\r\n                      </div>\r\n                      <div style={{ flex:1, position:\"relative\", padding:\"6px 4px\" }}>\r\n                        <div style={{ position:\"relative\", height:22,\r\n                                      background:\"#f8f9fa\", borderRadius:3 }}>\r\n                          {/* Grade de meses */}\r\n                          {meses.map((_,mi)=>(\r\n                            <div key={mi} style={{ position:\"absolute\",\r\n                                                    left:(mi/meses.length*100)+\"%\",\r\n                                                    top:0, bottom:0, width:1,\r\n                                                    background:\"rgba(0,0,0,.06)\" }}/>\r\n                          ))}\r\n                          {/* Barra */}\r\n                          {left!==null&&(w!==null||wAtivo!==null)&&(\r\n                            <div\r\n                              className=\"gantt-bar\"\r\n                              onMouseEnter={e=>handleMouseEnter(e,caso,ilha)}\r\n                              onMouseMove={e=>setTooltip(t=>t?{...t,x:e.clientX,y:e.clientY}:t)}\r\n                              onMouseLeave={handleMouseLeave}\r\n                              style={{\r\n                                position:\"absolute\",\r\n                                left:left+\"%\",\r\n                                width:(w||wAtivo)+\"%\",\r\n                                top:2, bottom:2,\r\n                                background:barCor,\r\n                                borderRadius:3,\r\n                                cursor:\"pointer\",\r\n                                display:\"flex\", alignItems:\"center\",\r\n                                paddingLeft:4, overflow:\"hidden\",\r\n                                boxShadow:ilha.status===\"Em andamento\"\r\n                                  ?\"0 0 8px rgba(26,111,196,.5)\":\"none\",\r\n                                border:ilha.status===\"Em andamento\"\r\n                                  ?\"1px solid rgba(26,111,196,.4)\":\"none\",\r\n                              }}>\r\n                              <span style={{ fontSize:8,color:\"#fff\",\r\n                                             whiteSpace:\"nowrap\",fontWeight:700 }}>\r\n                                {ilha.inicio}{ilha.fim?\" → \"+ilha.fim:\"\"}\r\n                              </span>\r\n                            </div>\r\n                          )}\r\n                          {left===null&&(\r\n                            <div style={{ position:\"absolute\",left:\"2%\",top:5,\r\n                                          fontSize:9,color:\"#bbb\" }}>\r\n                              Não iniciado\r\n                            </div>\r\n                          )}\r\n                        </div>\r\n                      </div>\r\n                    </div>\r\n                  );\r\n                })}\r\n              </div>\r\n            );\r\n          })}\r\n        </div>\r\n      </div>\r\n\r\n      {/* Legenda */}\r\n      <div id=\"gantt-legenda\" style={{ padding:\"10px 16px\", background:\"#f8f9fa\",\r\n                    borderTop:\"1px solid \"+C.cinzaL,\r\n                    display:\"flex\", gap:16, alignItems:\"center\" }}>\r\n        <span style={{ fontSize:10,color:C.cinzaT,fontWeight:700 }}>Legenda:</span>\r\n        {[[\"Concluída\",\"#1a8c4a\"],[\"Em andamento\",\"#1a6fc4\"],[\"Pendente\",\"#ddd\"]].map(([l,cor])=>(\r\n          <span key={l} style={{ display:\"flex\",alignItems:\"center\",gap:5,\r\n                                  fontSize:10,color:C.cinzaT }}>\r\n            <span style={{ width:24,height:8,background:cor,\r\n                           borderRadius:2,display:\"inline-block\" }}/>\r\n            {l}\r\n          </span>\r\n        ))}\r\n        <span style={{ marginLeft:\"auto\",fontSize:10,color:C.cinzaT,fontStyle:\"italic\" }}>\r\n          💡 Passe o mouse sobre as barras para detalhes\r\n        </span>\r\n      </div>\r\n    </div>\r\n  );\r\n}\r\n\r\n/* ── Categoria de casos na sidebar ── */\r\nfunction CategoriaCasos({ label, casos, cor, expanded, setExpanded, onSelect, bloqueado }) {\r\n  return (\r\n    <div>\r\n      <button onClick={()=>setExpanded(v=>!v)}\r\n        style={{ width:\"100%\",padding:\"8px 20px 8px 28px\",\r\n                 background:\"transparent\",border:\"none\",\r\n                 borderLeft:\"3px solid transparent\",\r\n                 display:\"flex\",alignItems:\"center\",\r\n                 justifyContent:\"space-between\",\r\n                 color:\"rgba(255,255,255,.6)\",\r\n                 fontSize:11,cursor:\"pointer\",textAlign:\"left\" }}>\r\n        <span>{label}</span>\r\n        <div style={{ display:\"flex\",alignItems:\"center\",gap:5 }}>\r\n          <span style={{ background:cor,color:\"#fff\",borderRadius:10,\r\n                         padding:\"1px 7px\",fontSize:9,fontWeight:700 }}>\r\n            {casos.length}\r\n          </span>\r\n          <span style={{ fontSize:9,color:\"rgba(255,255,255,.4)\" }}>\r\n            {expanded?\"▲\":\"▼\"}\r\n          </span>\r\n        </div>\r\n      </button>\r\n\r\n      {expanded&&(\r\n        <div style={{ background:\"rgba(0,0,0,.2)\" }}>\r\n          {casos.map(caso=>{\r\n            const ilhaAtiva=(ILHAS_DATA[caso.id]||[]).find(i=>i.status===\"Em andamento\");\r\n            return (\r\n              <button key={caso.id}\r\n                onClick={()=>!bloqueado&&onSelect(caso)}\r\n                style={{ width:\"100%\",padding:\"7px 16px 7px 40px\",\r\n                         background:\"transparent\",border:\"none\",\r\n                         borderLeft:\"3px solid transparent\",\r\n                         display:\"flex\",alignItems:\"center\",\r\n                         justifyContent:\"space-between\",\r\n                         cursor:bloqueado?\"not-allowed\":\"pointer\",\r\n                         borderBottom:\"1px solid rgba(255,255,255,.03)\",\r\n                         opacity:bloqueado?0.5:1 }}>\r\n                <div style={{ display:\"flex\",alignItems:\"center\",gap:6,\r\n                              flex:1,overflow:\"hidden\" }}>\r\n                  <span style={{ width:6,height:6,borderRadius:\"50%\",\r\n                                 background:cor,flexShrink:0 }}/>\r\n                  <span style={{ fontSize:11,color:\"rgba(255,255,255,.75)\",\r\n                                 overflow:\"hidden\",textOverflow:\"ellipsis\",\r\n                                 whiteSpace:\"nowrap\",textAlign:\"left\" }}>\r\n                    {caso.nome}\r\n                  </span>\r\n                </div>\r\n                {ilhaAtiva&&!bloqueado&&(\r\n                  <span style={{ display:\"flex\",alignItems:\"center\",justifyContent:\"center\",\r\n                                 width:16,height:16,borderRadius:4,flexShrink:0,marginLeft:4,\r\n                                 background:(ILHA_CORES[ilhaAtiva.nome]||{}).topo||\"#555\",\r\n                                 color:\"#fff\",opacity:0.85 }}>\r\n                    {ILHA_ICONES[ilhaAtiva.nome]}\r\n                  </span>\r\n                )}\r\n              </button>\r\n            );\r\n          })}\r\n        </div>\r\n      )}\r\n    </div>\r\n  );\r\n}\r\n\r\n\r\n/* ── Temas disponíveis ─────────────────────────── */\r\nconst TEMAS = [\r\n  { id:\"bege-watermark\",   nome:\"Bege Institucional\", desc:\"Marca d'água MPRJ-CI²\",       preview:\"#f5f0e8\" },\r\n  { id:\"bege-premium\",     nome:\"Bege Premium\",        desc:\"Grade + marca d'água\",         preview:\"#f7f3ec\" },\r\n  { id:\"cinza-suave\",      nome:\"Cinza Suave\",         desc:\"Gradiente limpo minimalista\",  preview:\"#f0f2f6\" },\r\n  { id:\"micro-grade\",      nome:\"Micro Grade\",         desc:\"Padrão governamental moderno\", preview:\"#f4f6f9\" },\r\n  { id:\"radial-elegante\",  nome:\"Radial Elegante\",     desc:\"Profundidade sutil bordô\",     preview:\"#f0f4f9\" },\r\n  { id:\"dark-premium\",     nome:\"Dark Premium\",        desc:\"Noir investigativo escuro\",    preview:\"#0f1520\" },\r\n  { id:\"branco-puro\",      nome:\"Branco Puro\",         desc:\"Ultra-minimalista\",            preview:\"#ffffff\" },\r\n  { id:\"azul-institucional\",nome:\"Azul Institucional\", desc:\"Gradiente azul MPRJ\",         preview:\"#e8f0fb\" },\r\n];\r\n\r\n/* ── Aplica estilo de fundo conforme tema ── */\r\nfunction getFundoStyle(temaId) {\r\n  switch(temaId) {\r\n    case \"bege-watermark\":    return { background:\"#f5f0e8\" };\r\n    case \"bege-premium\":      return { background:\"#f7f3ec\" };\r\n    case \"cinza-suave\":       return { background:\"linear-gradient(145deg,#eef1f8,#f0f4f9,#e8ecf4)\" };\r\n    case \"micro-grade\":       return { background:\"#f4f6f9\",\r\n                                       backgroundImage:\"linear-gradient(rgba(123,30,46,.04) 1px,transparent 1px),linear-gradient(90deg,rgba(123,30,46,.04) 1px,transparent 1px)\",\r\n                                       backgroundSize:\"28px 28px\" };\r\n    case \"radial-elegante\":   return { background:\"radial-gradient(ellipse at 15% 20%,rgba(123,30,46,.06),transparent 50%),radial-gradient(ellipse at 85% 80%,rgba(0,56,117,.04),transparent 50%),linear-gradient(135deg,#f0f4f9,#f4f6f9)\" };\r\n    case \"dark-premium\":      return { background:\"linear-gradient(135deg,#0f1520,#141c2e,#0d1117)\" };\r\n    case \"branco-puro\":       return { background:\"#ffffff\" };\r\n    case \"azul-institucional\":return { background:\"linear-gradient(145deg,#e8f0fb,#eef4fd,#e4eef8)\" };\r\n    default:                  return { background:\"#f5f0e8\" };\r\n  }\r\n}\r\n\r\n/* ── Componente de marca d'água ── */\r\nfunction MarcaDagua({ temaId }) {\r\n  const watermarkTemas = [\"bege-watermark\",\"bege-premium\",\"dark-premium\"];\r\n  if (!watermarkTemas.includes(temaId)) return null;\r\n  const isDark = temaId===\"dark-premium\";\r\n  const cor = isDark ? \"rgba(200,151,58,.04)\" : \"rgba(123,30,46,.065)\";\r\n  const rows = Array(10).fill(null);\r\n  return (\r\n    <div className=\"no-print\" style={{ position:\"fixed\", inset:0, overflow:\"hidden\",\r\n                  pointerEvents:\"none\", zIndex:0,\r\n                  transform:\"rotate(-25deg)\",\r\n                  transformOrigin:\"center center\" }}>\r\n      {rows.map((_,i)=>(\r\n        <div key={i} style={{ whiteSpace:\"nowrap\", padding:\"18px 0\",\r\n                              display:\"flex\", gap:\"40px\" }}>\r\n          {Array(8).fill(null).map((_,j)=>(\r\n            <span key={j} style={{ fontSize:12, fontWeight:800,\r\n                                   color:cor, letterSpacing:\".28em\",\r\n                                   fontFamily:\"'Plus Jakarta Sans',sans-serif\",\r\n                                   textTransform:\"uppercase\", userSelect:\"none\" }}>\r\n              MPRJ-CI² &nbsp; NAPPRA\r\n            </span>\r\n          ))}\r\n        </div>\r\n      ))}\r\n    </div>\r\n  );\r\n}\r\n\r\n/* ── Modal de Configurações ─────────────────────── */\r\nfunction ModalConfiguracoes({ onClose, temaAtual, setTema, usuario, temaCasoAtual, setTemaCasoLocal }) {\r\n  const [abaConf, setAbaConf] = useState(\"tema\");\r\n  const [temaHover, setTemaHover] = useState(null);\r\n  const [temaSelecionado, setTemaSelecionado] = useState(temaAtual);\r\n  const [temaCasoSel, setTemaCasoSel] = useState(temaCasoAtual||\"claro\");\r\n  const [diasAlerta, setDiasAlerta] = useState(()=>parseInt(localStorage.getItem(\"nappra_diasAlerta\")||\"7\",10));\r\n  const podeEditarAlerta = usuario.nivel===\"Administrador\"||usuario.nivel===\"Super Admin\";\r\n\r\n  const salvarAlertaConf = () => {\r\n    localStorage.setItem(\"nappra_diasAlerta\", String(diasAlerta));\r\n  };\r\n\r\n  const salvar = () => {\r\n    setTema(temaSelecionado);\r\n    localStorage.setItem(\"nappra_tema_\"+usuario.matricula, temaSelecionado);\r\n    if (setTemaCasoLocal) {\r\n      setTemaCasoLocal(temaCasoSel);\r\n      localStorage.setItem(\"nappra_tema_caso_\"+usuario.matricula, temaCasoSel);\r\n    }\r\n    onClose();\r\n  };\r\n\r\n  const restaurar = () => {\r\n    setTemaSelecionado(\"bege-watermark\");\r\n  };\r\n\r\n  const ABAS_CONF = [\r\n    { id:\"tema\",       icon:\"🎨\", label:\"Tema\" },\r\n    { id:\"tipografia\", icon:\"🔤\", label:\"Tipografia\" },\r\n    { id:\"densidade\",  icon:\"📐\", label:\"Densidade\" },\r\n    { id:\"alertas\",    icon:\"🔔\", label:\"Alertas\" },\r\n  ];\r\n\r\n  return (\r\n    <div style={{ position:\"fixed\", inset:0, zIndex:1000,\r\n                  background:\"rgba(0,0,0,.6)\",\r\n                  display:\"flex\", alignItems:\"center\", justifyContent:\"center\",\r\n                  backdropFilter:\"blur(4px)\" }}\r\n      onClick={e=>e.target===e.currentTarget&&onClose()}>\r\n\r\n      <div style={{ background:\"#fff\", borderRadius:12, width:660, maxHeight:\"85vh\",\r\n                    boxShadow:\"0 20px 60px rgba(0,0,0,.3)\",\r\n                    display:\"flex\", flexDirection:\"column\", overflow:\"hidden\" }}>\r\n\r\n        {/* Header */}\r\n        <div style={{ background:\"linear-gradient(90deg,#4a0810,#7B1E2E)\",\r\n                      padding:\"16px 24px\",\r\n                      display:\"flex\", alignItems:\"center\", justifyContent:\"space-between\",\r\n                      borderBottom:\"2px solid #D4A017\" }}>\r\n          <div>\r\n            <div style={{ fontFamily:\"'Instrument Serif',Georgia,serif\",\r\n                          fontSize:17, fontStyle:\"italic\", color:\"#fff\" }}>\r\n              Configurações do Sistema\r\n            </div>\r\n            <div style={{ fontSize:10, color:\"rgba(255,255,255,.45)\",\r\n                          marginTop:2, letterSpacing:\".06em\" }}>\r\n              Preferências salvas por usuário · {usuario.nome}\r\n            </div>\r\n          </div>\r\n          <button onClick={onClose}\r\n            style={{ background:\"rgba(255,255,255,.1)\", border:\"1px solid rgba(255,255,255,.2)\",\r\n                     borderRadius:6, width:30, height:30, color:\"rgba(255,255,255,.7)\",\r\n                     fontSize:16, cursor:\"pointer\", display:\"flex\",\r\n                     alignItems:\"center\", justifyContent:\"center\" }}>✕</button>\r\n        </div>\r\n\r\n        {/* Corpo */}\r\n        <div style={{ display:\"flex\", flex:1, overflow:\"hidden\" }}>\r\n\r\n          {/* Sidebar do modal */}\r\n          <div style={{ width:160, background:\"#f8f9fc\", borderRight:\"1px solid #e2e8f0\",\r\n                        padding:\"12px 0\", flexShrink:0 }}>\r\n            {ABAS_CONF.map(ab=>(\r\n              <button key={ab.id} onClick={()=>setAbaConf(ab.id)}\r\n                style={{ width:\"100%\", padding:\"10px 16px\",\r\n                         background:abaConf===ab.id?\"rgba(123,30,46,.08)\":\"transparent\",\r\n                         borderLeft:abaConf===ab.id?\"3px solid #7B1E2E\":\"3px solid transparent\",\r\n                         border:\"none\", display:\"flex\", alignItems:\"center\", gap:8,\r\n                         color:abaConf===ab.id?\"#7B1E2E\":\"#64748b\",\r\n                         fontSize:12, fontWeight:abaConf===ab.id?700:400,\r\n                         cursor:\"pointer\", textAlign:\"left\",\r\n                         fontFamily:\"'Plus Jakarta Sans',sans-serif\" }}>\r\n                <span>{ab.icon}</span>\r\n                {ab.label}\r\n              </button>\r\n            ))}\r\n          </div>\r\n\r\n          {/* Conteúdo */}\r\n          <div style={{ flex:1, padding:\"20px\", overflowY:\"auto\" }}>\r\n\r\n            {/* ABA TEMA */}\r\n            {abaConf===\"tema\"&&(\r\n              <>\r\n                <div style={{ fontSize:13, fontWeight:700, color:\"#1a1f2e\",\r\n                              marginBottom:4 }}>Escolha seu tema</div>\r\n                <div style={{ fontSize:11, color:\"#64748b\", marginBottom:16 }}>\r\n                  A preferência é salva individualmente por usuário.\r\n                  Passe o mouse para pré-visualizar.\r\n                </div>\r\n                <div style={{ fontSize:12, fontWeight:700, color:\"#7B1E2E\", marginBottom:10, letterSpacing:\".04em\", textTransform:\"uppercase\" }}>\r\n                  Tema da Página Inicial\r\n                </div>\r\n                <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(2,1fr)\", gap:10 }}>\r\n                  {TEMAS.map(t=>{\r\n                    const ativo = temaSelecionado===t.id;\r\n                    const hover = temaHover===t.id;\r\n                    return (\r\n                      <div key={t.id}\r\n                        onClick={()=>setTemaSelecionado(t.id)}\r\n                        onMouseEnter={()=>setTemaHover(t.id)}\r\n                        onMouseLeave={()=>setTemaHover(null)}\r\n                        style={{ border:\"2px solid \"+(ativo?\"#7B1E2E\":\"#e2e8f0\"),\r\n                                 borderRadius:8, overflow:\"hidden\", cursor:\"pointer\",\r\n                                 boxShadow:ativo?\"0 0 0 3px rgba(123,30,46,.15)\":\"none\",\r\n                                 transition:\"all .2s\" }}>\r\n                        {/* Preview do tema */}\r\n                        <div style={{ height:52, background:t.preview, position:\"relative\",\r\n                                      overflow:\"hidden\" }}>\r\n                          {(t.id===\"bege-watermark\"||t.id===\"bege-premium\")&&(\r\n                            <div style={{ position:\"absolute\", inset:-10,\r\n                                          transform:\"rotate(-25deg)\", overflow:\"hidden\",\r\n                                          fontSize:8, fontWeight:800,\r\n                                          color:\"rgba(123,30,46,.1)\",\r\n                                          letterSpacing:\".2em\", whiteSpace:\"nowrap\",\r\n                                          display:\"flex\", flexDirection:\"column\", gap:8 }}>\r\n                              <div>MPRJ-CI² NAPPRA MPRJ-CI² NAPPRA MPRJ-CI² NAPPRA</div>\r\n                              <div>NAPPRA MPRJ-CI² NAPPRA MPRJ-CI² NAPPRA MPRJ-CI²</div>\r\n                              <div>MPRJ-CI² NAPPRA MPRJ-CI² NAPPRA MPRJ-CI² NAPPRA</div>\r\n                              <div>NAPPRA MPRJ-CI² NAPPRA MPRJ-CI² NAPPRA MPRJ-CI²</div>\r\n                            </div>\r\n                          )}\r\n                          {t.id===\"micro-grade\"&&(\r\n                            <div style={{ position:\"absolute\", inset:0,\r\n                                          backgroundImage:\"linear-gradient(rgba(123,30,46,.06) 1px,transparent 1px),linear-gradient(90deg,rgba(123,30,46,.06) 1px,transparent 1px)\",\r\n                                          backgroundSize:\"14px 14px\" }}/>\r\n                          )}\r\n                          {t.id===\"dark-premium\"&&(\r\n                            <div style={{ position:\"absolute\", inset:0,\r\n                                          backgroundImage:\"linear-gradient(rgba(200,151,58,.08) 1px,transparent 1px),linear-gradient(90deg,rgba(200,151,58,.08) 1px,transparent 1px)\",\r\n                                          backgroundSize:\"14px 14px\" }}/>\r\n                          )}\r\n                          {ativo&&(\r\n                            <div style={{ position:\"absolute\", top:6, right:6,\r\n                                          width:18, height:18, borderRadius:\"50%\",\r\n                                          background:\"#7B1E2E\",\r\n                                          display:\"flex\", alignItems:\"center\",\r\n                                          justifyContent:\"center\" }}>\r\n                              <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\"\r\n                                strokeWidth=\"2.5\" width=\"10\" height=\"10\">\r\n                                <polyline points=\"20 6 9 17 4 12\"/>\r\n                              </svg>\r\n                            </div>\r\n                          )}\r\n                        </div>\r\n                        {/* Info do tema */}\r\n                        <div style={{ padding:\"8px 10px\",\r\n                                      background:ativo?\"rgba(123,30,46,.04)\":\"#fff\" }}>\r\n                          <div style={{ fontSize:11, fontWeight:700,\r\n                                        color:ativo?\"#7B1E2E\":\"#1a1f2e\" }}>{t.nome}</div>\r\n                          <div style={{ fontSize:9, color:\"#94a3b8\",\r\n                                        marginTop:1 }}>{t.desc}</div>\r\n                        </div>\r\n                      </div>\r\n                    );\r\n                  })}\r\n                </div>\r\n\r\n                {/* TEMA DO BANCO DOS CASOS */}\r\n                <div style={{ marginTop:24, borderTop:\"1px solid #e2e8f0\", paddingTop:20 }}>\r\n                  <div style={{ fontSize:12, fontWeight:700, color:\"#7B1E2E\", marginBottom:4, letterSpacing:\".04em\", textTransform:\"uppercase\" }}>\r\n                    Tema do Banco dos Casos\r\n                  </div>\r\n                  <div style={{ fontSize:11, color:\"#64748b\", marginBottom:14 }}>\r\n                    Estilo aplicado na tela individual de cada caso investigado.\r\n                  </div>\r\n                  <div style={{ display:\"grid\", gridTemplateColumns:\"repeat(2,1fr)\", gap:10 }}>\r\n                    {[\r\n                      { id:\"escuro\", nome:\"Escuro\", desc:\"Fundo escuro, ideal para análise noturna\",\r\n                        bg:\"#0f1520\", card:\"#1a1f2e\", text:\"#e2e8f0\" },\r\n                      { id:\"claro\",  nome:\"Claro\",  desc:\"Fundo claro, confortável para uso diurno\",\r\n                        bg:\"#f5f0e8\", card:\"#ffffff\", text:\"#1a1f2e\" },\r\n                    ].map(t=>{\r\n                      const ativo = temaCasoSel===t.id;\r\n                      return (\r\n                        <div key={t.id} onClick={()=>setTemaCasoSel(t.id)} style={{\r\n                          border:`2px solid ${ativo?\"#7B1E2E\":\"#e2e8f0\"}`,\r\n                          borderRadius:8, overflow:\"hidden\", cursor:\"pointer\",\r\n                          boxShadow:ativo?\"0 0 0 3px rgba(123,30,46,.15)\":\"none\",\r\n                          transition:\"all .2s\",\r\n                        }}>\r\n                          <div style={{ height:48, background:t.bg, position:\"relative\", display:\"flex\", gap:6, alignItems:\"flex-end\", padding:\"0 10px 8px\" }}>\r\n                            <div style={{ width:40, height:26, borderRadius:4, background:t.card, border:\"1px solid rgba(255,255,255,.1)\" }}/>\r\n                            <div style={{ flex:1, display:\"flex\", flexDirection:\"column\", gap:3 }}>\r\n                              <div style={{ height:5, borderRadius:2, background:t.text, opacity:.5, width:\"70%\" }}/>\r\n                              <div style={{ height:4, borderRadius:2, background:t.text, opacity:.25, width:\"45%\" }}/>\r\n                            </div>\r\n                            {ativo&&(\r\n                              <div style={{ position:\"absolute\", top:6, right:6, width:18, height:18, borderRadius:\"50%\", background:\"#7B1E2E\", display:\"flex\", alignItems:\"center\", justifyContent:\"center\" }}>\r\n                                <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" strokeWidth=\"2.5\" width=\"10\" height=\"10\"><polyline points=\"20 6 9 17 4 12\"/></svg>\r\n                              </div>\r\n                            )}\r\n                          </div>\r\n                          <div style={{ padding:\"8px 10px\", background:ativo?\"rgba(123,30,46,.04)\":\"#fff\" }}>\r\n                            <div style={{ fontSize:11, fontWeight:700, color:ativo?\"#7B1E2E\":\"#1a1f2e\" }}>{t.nome}</div>\r\n                            <div style={{ fontSize:9, color:\"#94a3b8\", marginTop:1 }}>{t.desc}</div>\r\n                          </div>\r\n                        </div>\r\n                      );\r\n                    })}\r\n                  </div>\r\n                </div>\r\n              </>\r\n            )}\r\n\r\n            {/* ABA ALERTAS */}\r\n            {abaConf===\"alertas\"&&(\r\n              <>\r\n                <div style={{ fontSize:13,fontWeight:700,color:\"#1a1f2e\",marginBottom:4 }}>\r\n                  Parâmetro de Alerta de Movimentação\r\n                </div>\r\n                <div style={{ fontSize:11,color:\"#64748b\",marginBottom:20,lineHeight:1.6 }}>\r\n                  Define quantos dias sem movimentação um caso precisa acumular para que seja emitido um alerta na barra superior.\r\n                  Esta configuração é <strong>global</strong> — aplica-se a todos os usuários do sistema.\r\n                </div>\r\n\r\n                {!podeEditarAlerta&&(\r\n                  <div style={{ background:\"#fff8f0\",border:\"1px solid #f0c060\",\r\n                                borderLeft:\"4px solid #c8973a\",borderRadius:6,\r\n                                padding:\"10px 14px\",marginBottom:16,\r\n                                fontSize:11,color:\"#8a5a00\",display:\"flex\",\r\n                                alignItems:\"center\",gap:8 }}>\r\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#c8973a\" strokeWidth=\"2\" width=\"14\" height=\"14\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><line x1=\"12\" y1=\"8\" x2=\"12\" y2=\"12\"/><line x1=\"12\" y1=\"16\" x2=\"12.01\" y2=\"16\"/></svg>\r\n                    <span>Apenas <strong>Administradores</strong> podem alterar este parâmetro.</span>\r\n                  </div>\r\n                )}\r\n\r\n                <div style={{ background:\"#f8f9fc\",border:\"1px solid #e2e8f0\",\r\n                              borderRadius:8,padding:\"16px 20px\",marginBottom:16 }}>\r\n                  <div style={{ fontSize:11,fontWeight:700,color:\"#1a1f2e\",marginBottom:10,\r\n                                display:\"flex\",alignItems:\"center\",gap:6 }}>\r\n                    <svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#7B1E2E\" strokeWidth=\"2\" width=\"14\" height=\"14\" strokeLinecap=\"round\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><polyline points=\"12 6 12 12 16 14\"/></svg>\r\n                    Dias sem movimentação para emitir alerta\r\n                  </div>\r\n                  <div style={{ display:\"flex\",alignItems:\"center\",gap:12 }}>\r\n                    <input type=\"number\" min=\"1\" max=\"365\"\r\n                      value={diasAlerta}\r\n                      onChange={e=>setDiasAlerta(Math.max(1,parseInt(e.target.value)||7))}\r\n                      disabled={!podeEditarAlerta}\r\n                      style={{ width:80,padding:\"8px 12px\",fontSize:16,fontWeight:800,\r\n                               textAlign:\"center\",border:\"2px solid \"+(podeEditarAlerta?\"#7B1E2E\":\"#e2e8f0\"),\r\n                               borderRadius:6,color:podeEditarAlerta?\"#7B1E2E\":\"#94a3b8\",\r\n                               background:podeEditarAlerta?\"#fff\":\"#f1f5f9\",\r\n                               fontFamily:\"'JetBrains Mono',monospace\",outline:\"none\" }}/>\r\n                    <div>\r\n                      <div style={{ fontSize:12,fontWeight:600,color:\"#1a1f2e\" }}>dias corridos</div>\r\n                      <div style={{ fontSize:10,color:\"#94a3b8\",marginTop:2 }}>\r\n                        Valor atual no sistema: <strong style={{ color:\"#7B1E2E\" }}>{parseInt(localStorage.getItem(\"nappra_diasAlerta\")||\"7\",10)} dias</strong>\r\n                      </div>\r\n                    </div>\r\n                  </div>\r\n                  {podeEditarAlerta&&(\r\n                    <button onClick={salvarAlertaConf}\r\n                      style={{ marginTop:12,padding:\"7px 16px\",background:\"#7B1E2E\",\r\n                               color:\"#fff\",border:\"none\",borderRadius:6,\r\n                               fontSize:11,fontWeight:700,cursor:\"pointer\",\r\n                               fontFamily:\"'Plus Jakarta Sans',sans-serif\",\r\n                               boxShadow:\"0 2px 6px rgba(123,30,46,.3)\" }}>\r\n                      Aplicar imediatamente\r\n                    </button>\r\n                  )}\r\n                </div>\r\n\r\n                <div style={{ background:\"#eef2ff\",border:\"1px solid #c7d2fe\",\r\n                              borderRadius:6,padding:\"10px 14px\",\r\n                              fontSize:11,color:\"#3730a3\",lineHeight:1.6 }}>\r\n                  <strong>ℹ️ Observação:</strong> O valor padrão é <strong>7 dias</strong>.\r\n                  Após alterar, os alertas são recalculados em tempo real para todos os usuários logados.\r\n                  Esta configuração não requer reinicialização do sistema.\r\n                </div>\r\n              </>\r\n            )}\r\n\r\n            {/* OUTRAS ABAS — em breve */}\r\n            {abaConf!==\"tema\"&&abaConf!==\"alertas\"&&(\r\n              <div style={{ display:\"flex\", flexDirection:\"column\",\r\n                            alignItems:\"center\", justifyContent:\"center\",\r\n                            height:\"100%\", gap:12, color:\"#94a3b8\" }}>\r\n                <div style={{ fontSize:36 }}>\r\n                  {ABAS_CONF.find(a=>a.id===abaConf)?.icon}\r\n                </div>\r\n                <div style={{ fontSize:14, fontWeight:700, color:\"#64748b\" }}>\r\n                  {ABAS_CONF.find(a=>a.id===abaConf)?.label}\r\n                </div>\r\n                <div style={{ fontSize:12, color:\"#94a3b8\", textAlign:\"center\",\r\n                              maxWidth:220 }}>\r\n                  Esta seção será implementada na próxima etapa.\r\n                </div>\r\n              </div>\r\n            )}\r\n          </div>\r\n        </div>\r\n\r\n        {/* Footer */}\r\n        <div style={{ padding:\"14px 24px\", borderTop:\"1px solid #e2e8f0\",\r\n                      display:\"flex\", justifyContent:\"space-between\",\r\n                      alignItems:\"center\", background:\"#f8f9fc\" }}>\r\n          <button onClick={restaurar}\r\n            style={{ fontSize:12, color:\"#94a3b8\", background:\"none\",\r\n                     border:\"1px solid #e2e8f0\", borderRadius:6,\r\n                     padding:\"7px 14px\", cursor:\"pointer\",\r\n                     fontFamily:\"'Plus Jakarta Sans',sans-serif\" }}>\r\n            Restaurar padrão\r\n          </button>\r\n          <div style={{ display:\"flex\", gap:8 }}>\r\n            <button onClick={onClose}\r\n              style={{ fontSize:12, color:\"#64748b\", background:\"#f1f5f9\",\r\n                       border:\"1px solid #e2e8f0\", borderRadius:6,\r\n                       padding:\"7px 16px\", cursor:\"pointer\",\r\n                       fontFamily:\"'Plus Jakarta Sans',sans-serif\" }}>\r\n              Cancelar\r\n            </button>\r\n            <button onClick={salvar}\r\n              style={{ fontSize:12, color:\"#fff\", background:\"#7B1E2E\",\r\n                       border:\"none\", borderRadius:6, padding:\"7px 20px\",\r\n                       cursor:\"pointer\", fontWeight:700,\r\n                       fontFamily:\"'Plus Jakarta Sans',sans-serif\",\r\n                       boxShadow:\"0 2px 8px rgba(123,30,46,.35)\" }}>\r\n              Salvar preferências\r\n            </button>\r\n          </div>\r\n        </div>\r\n      </div>\r\n    </div>\r\n  );\r\n}\r\n\r\n/* ══════════════════════════════════════════\r\n   TELA DE LOGIN\r\n══════════════════════════════════════════ */\r\nfunction TelaLogin({ onLogin }) {\r\n  const [usuario, setUsuario] = useState(\"\");\r\n  const [senha, setSenha]     = useState(\"\");\r\n  const [mostrar, setMostrar] = useState(false);\r\n  const [erro, setErro]       = useState(\"\");\r\n  const [loading, setLoading] = useState(false);\r\n  const [ok, setOk]           = useState(false);\r\n\r\n  const fazerLogin = () => {\r\n    setErro(\"\");\r\n    if (!usuario||!senha){setErro(\"Preencha sua matrícula e senha.\");return;}\r\n    setLoading(true);\r\n    setTimeout(()=>{\r\n      const user=USUARIOS_DB.find(u=>u.matricula===usuario&&u.senha===senha);\r\n      if(user){setOk(true);setTimeout(()=>onLogin(user),700);}\r\n      else{setErro(\"Matrícula ou senha incorretos.\");setSenha(\"\");setLoading(false);}\r\n    },800);\r\n  };\r\n\r\n  return (\r\n    <div style={{ minHeight:\"100vh\",display:\"flex\",flexDirection:\"column\",\r\n                  background:\"linear-gradient(160deg,#3d0610,#6b0f1e,#7b1e2e,#4a0b14)\",\r\n                  fontFamily:\"'Segoe UI',Arial,sans-serif\" }}>\r\n      <div style={{ background:\"linear-gradient(90deg,#6b0f1e,#7B1E2E,#6b0f1e)\",\r\n                    borderBottom:\"2px solid #c8973a\",height:58,\r\n                    display:\"flex\",alignItems:\"center\",padding:\"0 20px\",\r\n                    boxShadow:\"0 2px 16px rgba(0,0,0,.4)\" }}>\r\n        <img src={BRASAO} alt=\"MPRJ\" style={{ height:52,objectFit:\"contain\" }}/>\r\n        <div style={{ width:1.5,height:36,background:\"rgba(200,151,58,.55)\",margin:\"0 14px\" }}/>\r\n        <div style={{ fontSize:9,fontWeight:600,color:\"rgba(255,255,255,.72)\",\r\n                      letterSpacing:\".13em\",textTransform:\"uppercase\",lineHeight:1.4 }}>\r\n          MINISTÉRIO PÚBLICO<br/>DO ESTADO DO RIO DE JANEIRO\r\n        </div>\r\n      </div>\r\n      <div style={{ flex:1,display:\"flex\",alignItems:\"center\",justifyContent:\"center\",padding:20 }}>\r\n        <div style={{ width:\"100%\",maxWidth:420,background:\"#fff\",borderRadius:4,\r\n                      overflow:\"hidden\",boxShadow:\"0 8px 40px rgba(0,0,0,.4)\",\r\n                      border:\"1px solid rgba(123,30,46,.15)\" }}>\r\n          <div style={{ background:C.bordo,padding:\"26px 36px 22px\",\r\n                        textAlign:\"center\",position:\"relative\" }}>\r\n            <div style={{ position:\"absolute\",top:0,left:0,right:0,height:4,\r\n                          background:\"linear-gradient(90deg,#9B2335,#B5303F,#9B2335)\" }}/>\r\n            <div style={{ display:\"flex\",alignItems:\"center\",justifyContent:\"center\",\r\n                          gap:14,marginBottom:16 }}>\r\n              <img src={BRASAO} alt=\"MPRJ\" style={{ height:54 }}/>\r\n              <div style={{ width:1,height:48,background:\"rgba(255,255,255,.25)\" }}/>\r\n              <div style={{ textAlign:\"left\" }}>\r\n                <div style={{ fontSize:10,fontWeight:700,color:\"rgba(255,255,255,.55)\",\r\n                              textTransform:\"uppercase\",letterSpacing:\".14em\",lineHeight:1.5 }}>\r\n                  Ministério Público<br/>Estado do Rio de Janeiro\r\n                </div>\r\n                <div style={{ fontSize:13,fontWeight:700,color:\"rgba(255,255,255,.95)\",\r\n                              textTransform:\"uppercase\",letterSpacing:\".1em\",marginTop:3 }}>\r\n                  CI² · NAPPRA\r\n                </div>\r\n              </div>\r\n            </div>\r\n            <div style={{ fontSize:15,fontWeight:700,color:\"#fff\",lineHeight:1.4 }}>\r\n              Sistema de Investigação Patrimonial<br/>e Recuperação de Ativos\r\n            </div>\r\n            <div style={{ fontSize:10,color:\"rgba(255,255,255,.45)\",marginTop:5,\r\n                          letterSpacing:\".12em\",textTransform:\"uppercase\" }}>\r\n              Mineração · Análise · Inteligência\r\n            </div>\r\n            <div style={{ display:\"flex\",gap:8,justifyContent:\"center\",marginTop:12 }}>\r\n              <span style={{ fontSize:9,fontWeight:700,padding:\"3px 10px\",borderRadius:2,\r\n                             background:\"rgba(123,30,46,.25)\",color:\"#e8909a\",\r\n                             border:\"1px solid rgba(181,48,63,.4)\",textTransform:\"uppercase\" }}>\r\n                ⬤ Sigilo Investigativo\r\n              </span>\r\n              <span style={{ fontSize:9,fontWeight:700,padding:\"3px 10px\",borderRadius:2,\r\n                             background:\"rgba(255,255,255,.09)\",color:\"rgba(255,255,255,.6)\",\r\n                             border:\"1px solid rgba(255,255,255,.18)\",textTransform:\"uppercase\" }}>\r\n                Acesso Restrito\r\n              </span>\r\n            </div>\r\n          </div>\r\n          <div style={{ padding:\"28px 36px 24px\" }}>\r\n            <label style={{ display:\"block\",fontSize:11,fontWeight:700,color:C.cinzaT,\r\n                            textTransform:\"uppercase\",letterSpacing:\".1em\",marginBottom:7 }}>\r\n              Matrícula / Usuário\r\n            </label>\r\n            <input type=\"text\" value={usuario} onChange={e=>setUsuario(e.target.value)}\r\n              onKeyDown={e=>e.key===\"Enter\"&&document.getElementById(\"inp-s\").focus()}\r\n              placeholder=\"Digite sua matrícula MPRJ\"\r\n              style={{ width:\"100%\",padding:\"11px 14px\",border:\"1.5px solid \"+C.cinzaL,\r\n                       borderRadius:3,fontSize:14,outline:\"none\",\r\n                       background:\"#fafcff\",boxSizing:\"border-box\",marginBottom:16 }}/>\r\n            <label style={{ display:\"block\",fontSize:11,fontWeight:700,color:C.cinzaT,\r\n                            textTransform:\"uppercase\",letterSpacing:\".1em\",marginBottom:7 }}>\r\n              Senha de Acesso\r\n            </label>\r\n            <div style={{ position:\"relative\",marginBottom:8 }}>\r\n              <input id=\"inp-s\" type={mostrar?\"text\":\"password\"}\r\n                value={senha} onChange={e=>setSenha(e.target.value)}\r\n                onKeyDown={e=>e.key===\"Enter\"&&fazerLogin()} placeholder=\"••••••••••••\"\r\n                style={{ width:\"100%\",padding:\"11px 40px 11px 14px\",\r\n                         border:\"1.5px solid \"+C.cinzaL,borderRadius:3,\r\n                         fontSize:14,outline:\"none\",background:\"#fafcff\",\r\n                         boxSizing:\"border-box\" }}/>\r\n              <button onClick={()=>setMostrar(v=>!v)}\r\n                style={{ position:\"absolute\",right:10,top:\"50%\",transform:\"translateY(-50%)\",\r\n                         background:\"none\",border:\"none\",cursor:\"pointer\",\r\n                         fontSize:16,color:\"#999\" }}>\r\n                {mostrar?\"🙈\":\"👁\"}\r\n              </button>\r\n            </div>\r\n            <div style={{ display:\"flex\",justifyContent:\"space-between\",\r\n                          alignItems:\"center\",marginBottom:22 }}>\r\n              <span style={{ fontSize:12,color:C.cinzaT }}>\r\n                <input type=\"checkbox\" style={{ accentColor:C.bordo,marginRight:6 }}/>\r\n                Manter sessão ativa\r\n              </span>\r\n              <button style={{ fontSize:12,color:C.bordoM,background:\"none\",\r\n                               border:\"none\",cursor:\"pointer\" }}>\r\n                Esqueci minha senha\r\n              </button>\r\n            </div>\r\n            {erro&&(\r\n              <div style={{ marginBottom:14,padding:\"9px 13px\",background:\"#fdf2f4\",\r\n                            border:\"1px solid rgba(123,30,46,.22)\",borderRadius:3,\r\n                            fontSize:12,color:C.bordoM,textAlign:\"center\" }}>⚠ {erro}</div>\r\n            )}\r\n            <button onClick={fazerLogin} disabled={loading||ok}\r\n              style={{ width:\"100%\",padding:13,background:ok?C.verde:C.bordo,\r\n                       border:\"none\",borderRadius:3,fontSize:13,fontWeight:700,\r\n                       color:\"#fff\",letterSpacing:\".14em\",textTransform:\"uppercase\",\r\n                       cursor:\"pointer\",transition:\"background .3s\",\r\n                       boxShadow:\"0 3px 14px rgba(123,30,46,.3)\" }}>\r\n              {ok?\"✔  Acesso Autorizado — Carregando...\":loading?\"Verificando...\":\"Acessar o Sistema\"}\r\n            </button>\r\n            <div style={{ marginTop:16,padding:\"10px 13px\",background:\"#fdf7f8\",\r\n                          border:\"1px solid rgba(123,30,46,.15)\",\r\n                          borderLeft:\"3px solid \"+C.bordo,borderRadius:2 }}>\r\n              <p style={{ fontSize:10,color:\"#888\",lineHeight:1.65,margin:0 }}>\r\n                <strong style={{ color:C.bordoM }}>AVISO DE SEGURANÇA:</strong> Uso exclusivo\r\n                de servidores autorizados do MPRJ. Acessos não autorizados constituem crime\r\n                (Lei nº 14.155/2021). Todas as operações são registradas em log de auditoria.\r\n              </p>\r\n            </div>\r\n          </div>\r\n          <div style={{ borderTop:\"1px solid rgba(123,30,46,.18)\",padding:\"10px 36px\",\r\n                        display:\"flex\",justifyContent:\"space-between\",\r\n                        background:\"rgba(123,30,46,.04)\" }}>\r\n            <span style={{ fontSize:10,color:\"#aab4c4\" }}>v 1.0.0 · 2026</span>\r\n            <span style={{ fontSize:10,color:\"#aab4c4\" }}>CI² — NAPPRA / MPRJ</span>\r\n          </div>\r\n        </div>\r\n      </div>\r\n      <div style={{ background:C.bordo,borderTop:\"3px solid \"+C.bordoC,\r\n                    padding:\"8px 32px\",display:\"flex\",alignItems:\"center\",\r\n                    justifyContent:\"space-between\" }}>\r\n        <span style={{ fontSize:10,color:\"rgba(255,255,255,.38)\" }}>\r\n          CI² · NAPPRA — Sistema de Investigação Patrimonial e Recuperação de Ativos — MPRJ\r\n        </span>\r\n        <span style={{ fontSize:10,color:\"rgba(255,255,255,.5)\" }}>www.mprj.mp.br</span>\r\n      </div>\r\n    </div>\r\n  );\r\n}\r\n\r\n/* ── Relógio por extenso no rodapé ── */\r\nfunction RelogioRodape() {\r\n  const [agora, setAgora] = useState(new Date());\r\n  useEffect(() => {\r\n    const id = setInterval(() => setAgora(new Date()), 1000);\r\n    return () => clearInterval(id);\r\n  }, []);\r\n\r\n  const dias   = [\"domingo\",\"segunda-feira\",\"terça-feira\",\"quarta-feira\",\r\n                  \"quinta-feira\",\"sexta-feira\",\"sábado\"];\r\n  const meses  = [\"janeiro\",\"fevereiro\",\"março\",\"abril\",\"maio\",\"junho\",\r\n                  \"julho\",\"agosto\",\"setembro\",\"outubro\",\"novembro\",\"dezembro\"];\r\n  const p = n  => String(n).padStart(2,\"0\");\r\n\r\n  const texto = `Rio de Janeiro, ${dias[agora.getDay()]}, ${agora.getDate()} de ${meses[agora.getMonth()]} de ${agora.getFullYear()}  —  ${p(agora.getHours())}:${p(agora.getMinutes())}:${p(agora.getSeconds())}`;\r\n\r\n  return (\r\n    <span style={{ fontSize:10, color:\"rgba(255,255,255,.6)\",\r\n                   fontVariantNumeric:\"tabular-nums\",\r\n                   letterSpacing:\".03em\" }}>\r\n      {texto}\r\n    </span>\r\n  );\r\n}\r\n\r\n/* ══════════════════════════════════════════\r\n   CASO TESTE — DADOS RICOS (MOCK)\r\n══════════════════════════════════════════ */\r\nconst CASO_TESTE_DETALHE = {\r\n  id: 99,\r\n  nome: \"CASO LARANJA SECO\",\r\n  natureza: \"Investigação Patrimonial — Corrupção e Lavagem de Ativos\",\r\n  portaria: \"Port. CI²-NAPPRA nº 012/2026\",\r\n  resp: \"Det. Ana Paula Souza\",\r\n  equipe: [\"Det. Ana Paula Souza\", \"An. Carlos Lima\", \"An. Juliana Melo\", \"Per. Roberto Faria\"],\r\n  dataInicio: \"01/06/2026\",\r\n  objetoSumario: \"Investigação de esquema de corrupção envolvendo desvio de recursos públicos de contratos de obras, mediante utilização de empresas de fachada, laranjas e interpostas pessoas, com lavagem de ativos por meio de aquisição de imóveis, veículos de luxo, aeronaves e embarcações em valores incompatíveis com as rendas declaradas dos investigados.\",\r\n  ilhas: [\r\n    { id:\"estudo\", nome:\"Estudo de Caso\",  pct:100, status:\"Concluída\",    acc:\"#d4a84b\", dias:18, total:18, inicio:\"01/06/2026\", fim:\"18/06/2026\" },\r\n    { id:\"minera\", nome:\"Mineração\",        pct:62,  status:\"Em andamento\", acc:\"#a78bfa\", dias:26, total:42, inicio:\"19/06/2026\", fim:null         },\r\n    { id:\"osint\",  nome:\"OSINT\",            pct:10,  status:\"Em andamento\", acc:\"#60a5fa\", dias:4,  total:30, inicio:\"15/07/2026\", fim:null         },\r\n    { id:\"relat\",  nome:\"Relatório\",        pct:0,   status:\"Pendente\",     acc:\"#4ade80\", dias:0,  total:25, ini